update.foreach:
UPDATE T_LH_MOULD_CHANGE_PLAN
SET MOULD_STATUS = '1',
    UPDATE_TIME  = NOW()
WHERE FACTORY_CODE = #{item.factoryCode}
  AND SCHEDULE_DATE = #{item.scheduleDate}
  AND ORDER_NO = #{item.orderNo}
  AND LH_MACHINE_CODE = #{item.lhMachineCode}
  AND IS_DELETE = 0
  AND MOULD_STATUS = '0'

      AND LEFT_RIGHT_MOULD = #{item.leftRightMold}
